.cmd{width:480px;border:1px solid #8a8a8a;border-radius:12px;background:#fff;box-shadow:0 24px 48px -12px rgba(0,0,0,.3);font:15px system-ui,sans-serif;overflow:hidden}
.cmd__in{width:100%;min-height:52px;padding:0 16px;border:0;border-bottom:1px solid #d4d4d4;font:inherit}
.cmd__l{margin:0;padding:6px;list-style:none}
.cmd__l li{display:flex;justify-content:space-between;padding:10px;border-radius:8px}
.cmd__l [aria-selected=true]{background:#f0f0f0;font-weight:600}
.cmd kbd{font:12px ui-monospace,monospace;color:#525252}
/* interaction */
.cmd__s{margin:0;padding:8px 14px;font:13px system-ui,sans-serif;color:#525252;border-top:1px solid #e5e5e5}.cmd__s:empty{display:none}.cmd__none{padding:10px;color:#525252}

code.js:
const commands = [['New project', 'N'], ['Open settings', ','], ['Switch theme', 'T'], ['Export as PDF', 'E'], ['Search docs', '/']];
document.querySelectorAll('.cmd').forEach(box => {
  const input = box.querySelector('.cmd__in'), list = box.querySelector('[role=listbox]');
  const status = Object.assign(document.createElement('p'), { className: 'cmd__s' });
  status.setAttribute('role', 'status'); box.appendChild(status);
  let shown = commands, active = 0;
  const mark = i => {
    active = i; [...list.children].forEach((li, k) => li.setAttribute('aria-selected', String(k === i)));
    if (list.children[i]) input.setAttribute('aria-activedescendant', list.children[i].id);
  };
  const render = () => {
    const q = input.value.trim().toLowerCase();
    shown = commands.filter(c => c[0].toLowerCase().includes(q));
    list.innerHTML = shown.length ? shown.map((c, i) => '<li role="option" id="cmd-o' + i + '" aria-selected="false">' + c[0] + ' <kbd>' + c[1] + '</kbd></li>').join('') : '<li role="presentation" class="cmd__none">No results</li>';
    mark(shown.length ? 0 : -1);
  };
  const run = i => { if (shown[i]) { status.textContent = 'Ran: ' + shown[i][0]; input.value = ''; render(); } };
  input.addEventListener('input', render);
  input.addEventListener('keydown', e => {
    if (e.key === 'ArrowDown') { e.preventDefault(); mark(Math.min(shown.length - 1, active + 1)); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); mark(Math.max(0, active - 1)); }
    else if (e.key === 'Enter') { e.preventDefault(); run(active); }
    else if (e.key === 'Escape') { input.value = ''; render(); status.textContent = ''; }
  });
  list.addEventListener('click', e => { const li = e.target.closest('[role=option]'); if (li) run([...list.children].indexOf(li)); });
  render();
});
